class Solution {
    public int[] runningSum(int[] nums) {
        int[] run_sum = new int[nums.length];
        for( int i = 0; i<nums.length; i++){
            int sum = 0;
            for( int j = 0 ; j<=i ; j++){
                sum = sum + nums[j];
            }
            run_sum[i] = sum;
        }
        return run_sum;
    }
}
